insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (1, 'SPLDV', 'Mudah', 'Penyelesaian dari sistem persamaan linear dua variabel 2x + y = 7 dan x - y = 2 adalah ....', ARRAY['x = 4 dan y = -1', 'x = 1 dan y = 5', 'x = 3 dan y = 1', 'x = 2 dan y = 3'], 2, 'Eliminasi y: (2x + y) + (x - y) = 7 + 2 → 3x = 9 → x = 3. Substitusi ke x - y = 2 → 3 - y = 2 → y = 1.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (2, 'SPLDV', 'Mudah', 'Nilai x yang memenuhi sistem persamaan 3x + 2y = 12 dan x + y = 5 adalah ....', ARRAY['1', '2', '3', '4'], 1, 'Kalikan persamaan kedua dengan 2: 2x + 2y = 10. Kurangkan dari 3x + 2y = 12 → x = 2.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (3, 'SPLDV', 'Sedang', 'Harga 3 buku tulis dan 2 pensil adalah Rp13.000,00. Sedangkan harga 1 buku tulis dan 2 pensil adalah Rp7.000,00. Harga 1 buku tulis adalah ....', ARRAY['Rp3.000,00', 'Rp2.500,00', 'Rp3.500,00', 'Rp4.000,00'], 0, '(3b + 2p) - (b + 2p) = 13.000 - 7.000 → 2b = 6.000 → b = Rp3.000,00.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (4, 'SPLDV', 'Sedang', 'Jika (p, q) merupakan penyelesaian dari 4x - 3y = 18 dan 2x + y = 4, maka nilai dari p + 2q adalah ....', ARRAY['1', '5', '-5', '-1'], 3, 'Dari 2x + y = 4 → y = 4 - 2x. Substitusi: 4x - 3(4 - 2x) = 18 → 10x = 30 → x = p = 3, y = q = -2. Nilai p + 2q = 3 + 2(-2) = -1.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (5, 'SPLDV', 'Sedang', 'Keliling sebuah persegi panjang adalah 44 cm. Jika selisih panjang dan lebarnya adalah 6 cm, maka luas persegi panjang tersebut adalah ....', ARRAY['96 cm²', '108 cm²', '112 cm²', '120 cm²'], 2, '2(p + l) = 44 → p + l = 22 dan p - l = 6. Didapat 2p = 28 → p = 14 cm, l = 8 cm. Luas = 14 × 8 = 112 cm².') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (6, 'SPLDV', 'Mudah', 'Himpunan penyelesaian dari x + 2y = 8 dan x - y = 2 adalah ....', ARRAY['{(3, 1)}', '{(4, 2)}', '{(2, 4)}', '{(6, 1)}'], 1, '(x + 2y) - (x - y) = 8 - 2 → 3y = 6 → y = 2, x = 4.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (7, 'SPLDV', 'Sulit', 'Di tempat parkir terdapat 45 kendaraan yang terdiri atas sepeda motor dan mobil. Jumlah seluruh roda kendaraan tersebut adalah 120 roda. Banyak mobil di tempat parkir adalah ....', ARRAY['15 unit', '30 unit', '20 unit', '25 unit'], 0, 'm + b = 45 dan 2m + 4b = 120 → m + 2b = 60. Kurangkan: b = 60 - 45 = 15 mobil.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (8, 'SPLDV', 'Sedang', 'Jumlah dua bilangan cacah adalah 35 dan selisih kedua bilangan tersebut adalah 9. Hasil kali kedua bilangan tersebut adalah ....', ARRAY['276', '296', '306', '286'], 3, 'a + b = 35 dan a - b = 9 → 2a = 44 → a = 22, b = 13. Hasil kali = 22 × 13 = 286.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (9, 'SPLDV', 'Mudah', 'Grafik dari dua persamaan linear yang sejajar memiliki banyak penyelesaian sebanyak ....', ARRAY['Dua', 'Tak terhingga', 'Tidak ada (0)', 'Tepat satu'], 2, 'Dua garis yang sejajar tidak pernah berpotongan sehingga tidak memiliki titik potong (0 penyelesaian).') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (10, 'SPLDV', 'Sulit', 'Harga 2 kg apel dan 3 kg jeruk adalah Rp69.000,00, sedangkan harga 3 kg apel dan 2 kg jeruk adalah Rp76.000,00. Harga 1 kg apel dan 1 kg jeruk adalah ....', ARRAY['Rp28.000,00', 'Rp29.000,00', 'Rp27.000,00', 'Rp31.000,00'], 1, 'Jumlahkan kedua persamaan: 5a + 5j = 145.000 → dibagi 5 → a + j = Rp29.000,00.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (11, 'Bangun Ruang Sisi Datar', 'Mudah', 'Banyak rusuk dan titik sudut pada prisma segi enam beraturan berturut-turut adalah ....', ARRAY['18 dan 12', '12 dan 18', '18 dan 8', '12 dan 8'], 0, 'Prisma segi-n memiliki 3n rusuk (3×6 = 18) dan 2n titik sudut (2×6 = 12).') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (12, 'Bangun Ruang Sisi Datar', 'Mudah', 'Sebuah kubus memiliki panjang rusuk 9 cm. Luas permukaan kubus tersebut adalah ....', ARRAY['729 cm²', '324 cm²', '540 cm²', '486 cm²'], 3, 'Luas permukaan kubus = 6 × s² = 6 × 9² = 6 × 81 = 486 cm².') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (13, 'Bangun Ruang Sisi Datar', 'Sedang', 'Sebuah balok berukuran panjang 12 cm, lebar 8 cm, dan tinggi 5 cm. Luas permukaan balok tersebut adalah ....', ARRAY['196 cm²', '360 cm²', '392 cm²', '480 cm²'], 2, 'L = 2(pl + pt + lt) = 2(12×8 + 12×5 + 8×5) = 2(96 + 60 + 40) = 2(196) = 392 cm².') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (14, 'Bangun Ruang Sisi Datar', 'Sedang', 'Alas sebuah prisma berbentuk segitiga siku-siku dengan panjang sisi 6 cm, 8 cm, dan 10 cm. Jika tinggi prisma 15 cm, maka volume prisma adalah ....', ARRAY['300 cm³', '360 cm³', '720 cm³', '480 cm³'], 1, 'Luas alas = ½ × 6 × 8 = 24 cm². Volume = 24 × 15 = 360 cm³.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (15, 'Bangun Ruang Sisi Datar', 'Sedang', 'Sebuah limas persegi memiliki panjang sisi alas 10 cm dan tinggi limas 12 cm. Luas seluruh permukaan limas tersebut adalah ....', ARRAY['360 cm²', '340 cm²', '400 cm²', '260 cm²'], 0, 'Tinggi sisi tegak = √(12² + 5²) = 13 cm. L = L_alas + 4×L_segitiga = 100 + 4×(½×10×13) = 100 + 260 = 360 cm².') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (16, 'Bangun Ruang Sisi Datar', 'Mudah', 'Panjang kawat yang dibutuhkan untuk membuat satu kerangka balok berukuran 15 cm × 10 cm × 8 cm adalah ....', ARRAY['120 cm', '144 cm', '66 cm', '132 cm'], 3, 'Panjang kerangka = 4(p + l + t) = 4(15 + 10 + 8) = 4 × 33 = 132 cm.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (17, 'Bangun Ruang Sisi Datar', 'Sulit', 'Volume sebuah limas dengan alas berbentuk belah ketupat yang panjang diagonalnya 12 cm dan 16 cm serta tinggi limas 15 cm adalah ....', ARRAY['960 cm³', '720 cm³', '480 cm³', '1.440 cm³'], 2, 'L_alas = ½ × 12 × 16 = 96 cm². Volume limas = ⅓ × 96 × 15 = 480 cm³.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (18, 'Bangun Ruang Sisi Datar', 'Sedang', 'Panjang diagonal ruang sebuah kubus yang memiliki luas permukaan 294 cm² adalah ....', ARRAY['14√3 cm', '7√3 cm', '7√2 cm', '49√3 cm'], 1, '6s² = 294 → s² = 49 → s = 7 cm. Diagonal ruang kubus = s√3 = 7√3 cm.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (19, 'Bangun Ruang Sisi Datar', 'Mudah', 'Banyak diagonal bidang pada sebuah balok adalah ....', ARRAY['12', '4', '6', '8'], 0, 'Balok memiliki 6 sisi, setiap sisi memiliki 2 diagonal bidang, sehingga 6 × 2 = 12 diagonal bidang.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (20, 'Bangun Ruang Sisi Datar', 'Sulit', 'Sebuah kolam renang berbentuk balok berukuran panjang 10 m, lebar 6 m, dan kedalaman 1,5 m. Jika kolam diisi air hingga ⅘ bagian, volume air di dalam kolam adalah ....', ARRAY['90.000 liter', '60.000 liter', '80.000 liter', '72.000 liter'], 3, 'V_penuh = 10 × 6 × 1,5 = 90 m³ = 90.000 liter. Volume air = ⅘ × 90.000 = 72.000 liter.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (21, 'Lingkaran', 'Mudah', 'Sebuah lingkaran memiliki jari-jari 14 cm. Keliling lingkaran tersebut adalah .... (π = 22/7)', ARRAY['616 cm', '154 cm', '88 cm', '44 cm'], 2, 'K = 2 × π × r = 2 × (22/7) × 14 = 88 cm.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (22, 'Lingkaran', 'Mudah', 'Luas sebuah lingkaran yang berdiameter 20 cm adalah .... (π = 3,14)', ARRAY['157 cm²', '314 cm²', '62,8 cm²', '1.256 cm²'], 1, 'r = 10 cm. L = π × r² = 3,14 × 10² = 314 cm².') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (23, 'Lingkaran', 'Sedang', 'Diketahui sudut pusat AOB pada lingkaran adalah 72° dan panjang jari-jarinya 21 cm. Panjang busur AB adalah .... (π = 22/7)', ARRAY['26,4 cm', '13,2 cm', '52,8 cm', '277,2 cm'], 0, 'Panjang busur = (72°/360°) × 2 × (22/7) × 21 = ⅕ × 132 = 26,4 cm.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (24, 'Lingkaran', 'Sedang', 'Luas juring lingkaran dengan sudut pusat 90° dan jari-jari 14 cm adalah .... (π = 22/7)', ARRAY['616 cm²', '308 cm²', '77 cm²', '154 cm²'], 3, 'Luas juring = (90°/360°) × (22/7) × 14² = ¼ × 616 = 154 cm².') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (25, 'Lingkaran', 'Mudah', 'Jika besar sudut pusat AOB = 110°, maka besar sudut keliling ACB yang menghadap busur yang sama adalah ....', ARRAY['110°', '70°', '55°', '220°'], 2, 'Sudut keliling = ½ × sudut pusat = ½ × 110° = 55°.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (26, 'Lingkaran', 'Sedang', 'Panjang garis singgung persekutuan luar dua lingkaran yang berjari-jari 10 cm dan 4 cm dengan jarak kedua pusat 10 cm adalah ....', ARRAY['9 cm', '8 cm', '6 cm', '12 cm'], 1, 'd = √(p² - (R - r)²) = √(10² - (10 - 4)²) = √(100 - 36) = √64 = 8 cm.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (27, 'Lingkaran', 'Sulit', 'Jarak pusat dua lingkaran adalah 17 cm. Jika panjang jari-jari kedua lingkaran masing-masing 5 cm dan 3 cm, panjang garis singgung persekutuan dalamnya adalah ....', ARRAY['15 cm', '12 cm', '16 cm', '14 cm'], 0, 'd = √(p² - (R + r)²) = √(17² - (5 + 3)²) = √(289 - 64) = √225 = 15 cm.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (28, 'Lingkaran', 'Sedang', 'Sebuah roda sepeda berjari-jari 35 cm berputar sebanyak 100 kali. Jarak yang ditempuh sepeda tersebut adalah .... (π = 22/7)', ARRAY['110 meter', '22 meter', '440 meter', '220 meter'], 3, 'K = 2 × (22/7) × 35 = 220 cm. Jarak = 220 cm × 100 = 22.000 cm = 220 meter.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (29, 'Lingkaran', 'Mudah', 'Daerah di dalam lingkaran yang dibatasi oleh dua jari-jari dan satu busur lingkaran disebut ....', ARRAY['Apotema', 'Tali busur', 'Juring', 'Tembereng'], 2, 'Juring adalah daerah yang dibatasi oleh dua jari-jari dan busur lingkaran.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (30, 'Lingkaran', 'Sulit', 'Sebuah taman berbentuk lingkaran berdiameter 28 m akan ditanami rumput dengan biaya Rp25.000,00 per m². Total biaya penanaman rumput adalah .... (π = 22/7)', ARRAY['Rp14.000.000,00', 'Rp15.400.000,00', 'Rp61.600.000,00', 'Rp7.700.000,00'], 1, 'r = 14 m. Luas = (22/7) × 14² = 616 m². Biaya = 616 × 25.000 = Rp15.400.000,00.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (31, 'Bangun Ruang Sisi Lengkung', 'Mudah', 'Sebuah tabung memiliki jari-jari alas 7 cm dan tinggi 10 cm. Volume tabung tersebut adalah .... (π = 22/7)', ARRAY['1.540 cm³', '440 cm³', '748 cm³', '3.080 cm³'], 0, 'V = π × r² × t = (22/7) × 49 × 10 = 1.540 cm³.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (32, 'Bangun Ruang Sisi Lengkung', 'Mudah', 'Luas selimut sebuah tabung dengan jari-jari 14 cm dan tinggi 20 cm adalah .... (π = 22/7)', ARRAY['2.992 cm²', '880 cm²', '1.232 cm²', '1.760 cm²'], 3, 'L_selimut = 2 × π × r × t = 2 × (22/7) × 14 × 20 = 1.760 cm².') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (33, 'Bangun Ruang Sisi Lengkung', 'Sedang', 'Sebuah kerucut memiliki jari-jari alas 6 cm dan tinggi 8 cm. Luas selimut kerucut tersebut adalah .... (π = 3,14)', ARRAY['150,72 cm²', '113,04 cm²', '188,4 cm²', '301,44 cm²'], 2, 'Garis pelukis s = √(6² + 8²) = 10 cm. L_selimut = π × r × s = 3,14 × 6 × 10 = 188,4 cm².') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (34, 'Bangun Ruang Sisi Lengkung', 'Sedang', 'Volume sebuah kerucut yang berdiameter 14 cm dan tinggi 12 cm adalah .... (π = 22/7)', ARRAY['308 cm³', '616 cm³', '1.848 cm³', '2.464 cm³'], 1, 'r = 7 cm. V = ⅓ × π × r² × t = ⅓ × (22/7) × 49 × 12 = 616 cm³.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (35, 'Bangun Ruang Sisi Lengkung', 'Mudah', 'Luas permukaan sebuah bola yang memiliki jari-jari 7 cm adalah .... (π = 22/7)', ARRAY['616 cm²', '154 cm²', '308 cm²', '1.437,3 cm²'], 0, 'L_bola = 4 × π × r² = 4 × (22/7) × 49 = 616 cm².') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (36, 'Bangun Ruang Sisi Lengkung', 'Sedang', 'Volume sebuah bola yang berjari-jari 21 cm adalah .... (π = 22/7)', ARRAY['5.544 cm³', '19.404 cm³', '12.936 cm³', '38.808 cm³'], 3, 'V = (4/3) × π × r³ = (4/3) × (22/7) × 21 × 21 × 21 = 38.808 cm³.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (37, 'Bangun Ruang Sisi Lengkung', 'Sulit', 'Sebuah bandul terdiri dari kerucut dan belahan bola yang berimpit pada alasnya. Jika jari-jari keduanya 7 cm dan tinggi kerucut 24 cm, luas permukaan bandul tersebut adalah .... (π = 22/7)', ARRAY['308 cm²', '1.166 cm²', '858 cm²', '550 cm²'], 2, 's = √(7² + 24²) = 25 cm. L = L_selimut_kerucut + L_setengah_bola = (22/7×7×25) + (2×22/7×49) = 550 + 308 = 858 cm².') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (38, 'Bangun Ruang Sisi Lengkung', 'Sedang', 'Perbandingan volume tabung dan volume kerucut yang memiliki jari-jari dan tinggi yang sama adalah ....', ARRAY['4 : 3', '3 : 1', '1 : 3', '2 : 1'], 1, 'V_tabung = πr²t dan V_kerucut = ⅓πr²t, sehingga perbandingannya adalah 3 : 1.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (39, 'Bangun Ruang Sisi Lengkung', 'Sulit', 'Sebuah kubah masjid berbentuk setengah bola dengan diameter 14 m akan dicat bagian luarnya. Jika 1 kaleng cat cukup untuk mengecat 11 m², banyak cat yang dibutuhkan adalah .... (π = 22/7)', ARRAY['28 kaleng', '56 kaleng', '14 kaleng', '42 kaleng'], 0, 'r = 7 m. L_setengah_bola = 2 × (22/7) × 49 = 308 m². Banyak cat = 308 / 11 = 28 kaleng.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
insert into public.questions (id, topic, diff, q, options, answer_idx, explanation) values (40, 'Bangun Ruang Sisi Lengkung', 'Sulit', 'Sebuah tabung berisi penuh air dengan jari-jari 10 cm dan tinggi 30 cm. Ke dalam tabung dimasukkan sebuah bola pejal berjari-jari 10 cm hingga tenggelam seluruhnya. Volume air yang tumpah adalah .... (π = 3,14)', ARRAY['9.420 cm³', '3.140 cm³', '1.256 cm³', '4.186,67 cm³'], 3, 'Air yang tumpah = Volume bola = (4/3) × 3,14 × 10³ = 12.560 / 3 = 4.186,67 cm³.') on conflict (id) do update set topic=excluded.topic, diff=excluded.diff, q=excluded.q, options=excluded.options, answer_idx=excluded.answer_idx, explanation=excluded.explanation;
